standard_solution_code:
from typing import List
import collections

class Solution:

	def minimumMultiplications(self, arr: List[int], start: int, end: int) -> int:
		que = collections.deque()
		que.append((start, 0))
		distance = [float('inf') for _ in range(100000)]
		distance[start] = 0
		while que:
			(currNum, step) = que.popleft()
			for num in arr:
				nextnum = int(currNum * num % 100000)
				if step + 1 < distance[nextnum]:
					que.append((nextnum, step + 1))
					if nextnum == end:
						return step + 1
					distance[nextnum] = step + 1
		return -1
